// Value resolution: a port of src/formcast/render/values.py (and the severities of
// src/formcast/render/report.py). What each template field should say, from one data record. No PDF
// involved.
//
// Python is the reference. tests/web/fixtures/values.json is generated by running the Python library
// (demo/tools/export_conformance.py) and values.test.js holds this file to it, messages included.
//
// `resolve` turns `(template, record)` into per-field results, per-table cell targets, and
// record-level warnings. It never throws on bad *data* (that is reported); a bad template schema
// still throws (SchemaError from flattenSchema). Results are plain objects with the keys of Python's
// `Resolved`, `CellTarget` and `TableResolved` dataclasses; a warning is `{code, severity, message,
// path, field, page, rect}` with null for what is not set.
//
// Missing means: absent key, null, "", a whitespace-only string, or an empty list. 0 and false are
// values.
//
// Two differences from Python, both because the browser has no JSON Schema validator:
// - the record is not validated, so no record-level `invalid` warning is produced (a row that cannot
//   supply table cells is still reported `invalid`, as in Python);
// - a record key the schema does not declare is always reported in `unknown_keys`, also under an
//   object whose schema forbids extra properties (Python leaves those to its `invalid` warnings).

import {
  decimalDigitValue,
  hasKey,
  isDict,
  pyRepr,
  pyStrip,
  pyTruthy,
  pyTypeName,
} from "./pycompat.js";
import { ARRAY_ITEM, PathError, flattenSchema, formatPath, isArrayItem, parsePath } from "./schema.js";
import { TransformError, applyChain, boolToCheck, toText } from "./transforms.js";

const CHOICE_TYPES = ["checkbox", "radio_option", "choice_mark"];

const INFO = new Set(["shrunk", "adopted", "font_substituted", "list_joined", "unknown_keys"]);

/** Every warning code and its severity (`"info"` for the five informational ones, else `"warning"`). */
export const SEVERITY = Object.freeze(
  Object.fromEntries(
    [
      "missing",
      "invalid",
      "transform_error",
      "unmapped_data",
      "shrunk",
      "overflow",
      "truncated",
      "unencodable",
      "rows_dropped",
      "widget_not_found",
      "type_mismatch",
      "not_writable",
      "not_an_option",
      "shared_field_conflict",
      "adopted",
      "font_substituted",
      "list_joined",
      "unknown_keys",
      "fingerprint_mismatch",
      "not_shown",
    ].map((code) => [code, INFO.has(code) ? "info" : "warning"]),
  ),
);

/**
 * @typedef {object} FillWarning
 * @property {string} code
 * @property {"warning"|"info"} severity
 * @property {string} message
 * @property {string|null} path
 * @property {string|null} field
 * @property {number|null} page
 * @property {number[]|null} rect
 */

/**
 * Build a warning whose severity comes from SEVERITY.
 * @param {string} code
 * @param {string} message
 * @param {{path?: string|null, field?: string|null, page?: number|null, rect?: number[]|null}} [where]
 * @returns {FillWarning}
 */
export function makeWarning(code, message, { path = null, field = null, page = null, rect = null } = {}) {
  if (!hasKey(SEVERITY, code)) throw new Error(`unknown warning code ${pyRepr(code)}`);
  return { code, severity: SEVERITY[code], message, path, field, page, rect: rect === null ? null : [...rect] };
}

/**
 * @typedef {object} Resolved
 * @property {string} field_id
 * @property {"text"|"choice"} kind
 * @property {string[]} paths
 * @property {boolean} has_value  at least one source value is not missing
 * @property {string|null} text
 * @property {boolean|null} on
 * @property {FillWarning[]} warnings
 *
 * @typedef {object} CellTarget
 * @property {string} table_id
 * @property {number} segment
 * @property {number} row
 * @property {string} key
 * @property {number} page
 * @property {number[]} rect
 * @property {string|null} text
 * @property {FillWarning[]} warnings
 *
 * @typedef {object} TableResolved
 * @property {string} field_id
 * @property {string} path
 * @property {number} rows_provided
 * @property {CellTarget[]} cells
 * @property {number[]} rows_per_segment
 * @property {number} rows_dropped
 * @property {FillWarning[]} warnings
 */

/**
 * True for null, a blank (empty or whitespace-only) string, or an empty list.
 * @param {unknown} v
 * @returns {boolean}
 */
export function isMissing(v) {
  if (v === null || v === undefined) return true;
  if (typeof v === "string") return pyStrip(v) === "";
  if (Array.isArray(v)) return v.length === 0;
  return false;
}

/**
 * Follow `path` through objects; null for anything absent. `[]` paths are not looked up here.
 * @param {unknown} data
 * @param {string} path
 * @returns {any}
 */
export function lookup(data, path) {
  let segments;
  try {
    segments = parsePath(path);
  } catch (e) {
    if (e instanceof PathError) return null;
    throw e;
  }
  let cur = data;
  for (const seg of segments) {
    if (isArrayItem(seg) || !isDict(cur)) return null;
    cur = hasKey(cur, seg) ? cur[seg] : null;
  }
  return cur === undefined ? null : cur;
}

// ---------------------------------------------------------------- text values

/**
 * Final text for a transformed value, and whether a list was implicitly joined.
 * Throws TransformError if an item cannot be rendered as text.
 * @returns {[string|null, boolean]}
 */
function render(result, join = null) {
  if (Array.isArray(result)) {
    const items = result.filter((x) => !isMissing(x)).map(toText);
    if (!items.length) return [null, false];
    if (join !== null) return [items.join(join), false];
    return [items.join(", "), true];
  }
  if (isMissing(result)) return [null, false];
  return [toText(result), false];
}

function sourceValues(f, data) {
  return f.source.paths.map((p) => {
    const v = lookup(data, p);
    return isMissing(v) ? null : v;
  });
}

function whereOf(f, src) {
  return { field: f.id, page: f.page ?? null, rect: f.rect ?? null, path: src.paths.length === 1 ? src.paths[0] : null };
}

function resolveText(f, data) {
  const src = f.source;
  const values = sourceValues(f, data);
  const res = {
    field_id: f.id,
    kind: "text",
    paths: [...src.paths],
    has_value: values.some((v) => v !== null),
    text: null,
    on: null,
    warnings: [],
  };
  const where = whereOf(f, src);
  let text;
  let joined;
  try {
    const result = applyChain(values, src.transforms ?? []);
    [text, joined] = render(result, src.join ?? null);
  } catch (e) {
    if (!(e instanceof TransformError)) throw e;
    res.warnings.push(makeWarning("transform_error", e.message, where));
    return res;
  }
  if (text === null) {
    const why = res.has_value ? "the transforms left no value for" : "no value for";
    res.warnings.push(makeWarning("missing", `${why} ${src.paths.join(", ")}`, where));
  } else if (joined) {
    res.warnings.push(makeWarning("list_joined", `list value joined with ', ' into ${pyRepr(text)}`, where));
  }
  res.text = text;
  return res;
}

/**
 * Whether a choice box with source `source` is on for these source `values`: runs the transforms,
 * then `when` (or bool_to_check without one). Throws TransformError when a transform rejects a value.
 * @param {{transforms?: object[], when?: object|null}} source
 * @param {unknown[]} values
 * @returns {boolean}
 */
export function choiceOn(source, values) {
  const x = applyChain(values, source.transforms ?? []);
  if (source.when !== undefined && source.when !== null) return pyTruthy(applyChain([x], [source.when]));
  return boolToCheck(x);
}

function resolveChoice(f, data) {
  const src = f.source;
  const values = sourceValues(f, data);
  const hasValue = values.some((v) => v !== null);
  const res = { field_id: f.id, kind: "choice", paths: [...src.paths], has_value: hasValue, text: null, on: false, warnings: [] };
  const where = whereOf(f, src);
  if (!hasValue) {
    res.warnings.push(makeWarning("missing", `no value for ${src.paths.join(", ")}`, where));
    return res;
  }
  try {
    res.on = choiceOn(src, values);
  } catch (e) {
    if (!(e instanceof TransformError)) throw e;
    res.on = false;
    res.warnings.push(makeWarning("transform_error", e.message, where));
  }
  return res;
}

// --------------------------------------------------------------------- tables

/** A column key is a row-relative schema path (`dose`, `sched.time`, `["dose mg"]`). */
function keySegments(key) {
  try {
    return parsePath(key);
  } catch (e) {
    if (e instanceof PathError) return [key];
    throw e;
  }
}

/** Python's `int(text)` for a column key, or null where it raises ValueError. */
function pyInt(text) {
  const s = pyStrip(text);
  const sign = s.startsWith("-") ? -1 : 1;
  const chars = Array.from(s.startsWith("-") || s.startsWith("+") ? s.slice(1) : s);
  if (!chars.length) return null;
  let n = 0;
  let prevDigit = false;
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] === "_") {
      // an underscore may only separate two digits
      if (!prevDigit || i === chars.length - 1) return null;
      prevDigit = false;
      continue;
    }
    const d = decimalDigitValue(chars[i]);
    if (d < 0) return null;
    n = n * 10 + d;
    prevDigit = true;
  }
  return sign * n;
}

function cellValue(row, key) {
  if (isDict(row)) {
    let cur = row;
    for (const seg of keySegments(key)) {
      if (isArrayItem(seg) || !isDict(cur)) return null;
      cur = hasKey(cur, seg) ? cur[seg] : null;
    }
    return cur;
  }
  if (Array.isArray(row)) {
    let i = pyInt(key);
    if (i === null) return null;
    if (i < 0) i += row.length;
    return i >= 0 && i < row.length ? row[i] : null;
  }
  return null;
}

/** Why `row` cannot supply cells, or null when it can. */
function rowProblem(row, itemType) {
  if (row === null || row === undefined) return "row is null";
  if (isDict(row)) {
    return itemType === null || itemType === "object" ? null : `row is an object but the schema expects ${itemType}`;
  }
  if (Array.isArray(row)) {
    return itemType === null || itemType === "array" ? null : `row is a list but the schema expects ${itemType}`;
  }
  return `row is ${pyTypeName(row)} ${pyRepr(row)}, expected ${itemType === "object" ? "an object" : "a row"}`;
}

function resolveTable(f, data, byPath) {
  const path = f.source.paths[0];
  const itemType = byPath.has(path) ? byPath.get(path).item_type : null;
  const out = {
    field_id: f.id,
    path,
    rows_provided: 0,
    cells: [],
    rows_per_segment: f.segments.map(() => 0),
    rows_dropped: 0,
    warnings: [],
  };
  const where = { field: f.id, path, page: f.segments[0].page };
  const rows = lookup(data, path);
  if (isMissing(rows)) {
    out.warnings.push(makeWarning("missing", `no rows for ${path}`, where));
    return out;
  }
  if (!Array.isArray(rows)) {
    out.warnings.push(makeWarning("invalid", `${path} should be a list of rows but is ${pyTypeName(rows)}`, where));
    return out;
  }
  out.rows_provided = rows.length;

  let cursor = 0; // next row to place
  f.segments.forEach((seg, k) => {
    const take = Math.max(0, Math.min(seg.max_rows, rows.length - cursor));
    out.rows_per_segment[k] = take;
    for (let r = 0; r < take; r++) {
      const index = cursor + r;
      const row = rows[index];
      const y = seg.row_top + r * seg.row_height;
      const problem = rowProblem(row, itemType);
      if (problem !== null) {
        out.warnings.push(
          makeWarning("invalid", `${path} row ${index}: ${problem}; its cells are left empty`, {
            ...where,
            page: seg.page,
            rect: [seg.rect[0], y, seg.rect[2], y + seg.row_height],
          }),
        );
      }
      for (const col of seg.columns) {
        const rect = [col.x[0], y, col.x[1], y + seg.row_height];
        const cell = { table_id: f.id, segment: k, row: index, key: col.key, page: seg.page, rect, text: null, warnings: [] };
        out.cells.push(cell);
        if (problem !== null) continue;
        const value = cellValue(row, col.key);
        const cwhere = { field: f.id, path: `${path}[].${col.key}`, page: seg.page, rect };
        let joined;
        try {
          const result = applyChain([isMissing(value) ? null : value], col.transforms ?? []);
          [cell.text, joined] = render(result);
        } catch (e) {
          if (!(e instanceof TransformError)) throw e;
          cell.warnings.push(makeWarning("transform_error", e.message, cwhere));
          continue;
        }
        if (joined) {
          cell.warnings.push(makeWarning("list_joined", `list value joined with ', ' into ${pyRepr(cell.text)}`, cwhere));
        }
      }
    }
    cursor += take;
  });
  out.rows_dropped = rows.length - cursor;
  if (out.rows_dropped) {
    const last = f.segments[f.segments.length - 1];
    out.warnings.push(
      makeWarning(
        "rows_dropped",
        `${out.rows_dropped} of ${rows.length} rows don't fit the table's ${f.segments.length} segment(s) and were dropped`,
        { ...where, page: last.page },
      ),
    );
  }
  return out;
}

// --------------------------------------------------------------- record level

function valuesAt(node, segments, out) {
  if (!segments.length) {
    out.push(node);
    return;
  }
  const [head, ...rest] = segments;
  if (isArrayItem(head)) {
    if (Array.isArray(node)) for (const item of node) valuesAt(item, rest, out);
  } else if (isDict(node) && hasKey(node, head)) {
    valuesAt(node[head], rest, out);
  }
}

/** Whether any value reachable at schema path `path` is not missing (`[]` fans out over list items). */
function hasValueAt(data, path) {
  const found = [];
  valuesAt(data, parsePath(path), found);
  return found.some((v) => !isMissing(v));
}

/** Python compares segments as strings, so a property named "[]" equals the array-item marker here. */
function startsWith(segs, prefix) {
  return prefix.length <= segs.length && prefix.every((p, i) => String(p) === String(segs[i]));
}

/** Schema paths the template maps: exact paths, covering prefixes, and mapped table paths. */
function covered(fields, byPath) {
  const exact = new Set();
  const prefixes = [];
  const tables = new Set();
  for (const f of fields) {
    if (!f.source || !f.source.paths.length) continue;
    if (f.type !== "table") {
      for (const p of f.source.paths) {
        exact.add(p);
        try {
          prefixes.push(parsePath(p));
        } catch (e) {
          if (!(e instanceof PathError)) throw e;
        }
      }
      continue;
    }
    const p = f.source.paths[0];
    exact.add(p);
    tables.add(p);
    let segs;
    try {
      segs = parsePath(p);
    } catch (e) {
      if (!(e instanceof PathError)) throw e;
      continue;
    }
    if (byPath.has(p) && byPath.get(p).item_type !== "object") {
      prefixes.push(segs); // list-of-list / list-of-scalar rows: the whole subtree is the table's
    } else {
      for (const seg of f.segments) for (const c of seg.columns) prefixes.push([...segs, ARRAY_ITEM, ...keySegments(c.key)]);
    }
  }
  return { exact, prefixes, tables };
}

function unmapped(template, data, schemaPaths) {
  const byPath = new Map(schemaPaths.map((sp) => [sp.path, sp]));
  const { exact, prefixes, tables } = covered(template.fields, byPath);
  const out = [];
  for (const sp of schemaPaths) {
    if (sp.type === "object" || (sp.in_table !== null && !tables.has(sp.in_table))) continue;
    const segs = parsePath(sp.path);
    if (isArrayItem(segs[segs.length - 1])) continue;
    if (exact.has(sp.path) || prefixes.some((pre) => startsWith(segs, pre))) continue;
    if (hasValueAt(data, sp.path)) {
      out.push(makeWarning("unmapped_data", `the record has a value at ${pyRepr(sp.path)} but no template field maps it`, { path: sp.path }));
    }
  }
  return out;
}

/** Schema-style paths of record keys the schema does not declare. */
function unknownKeys(data, known) {
  const found = [];
  const walk = (node, segs) => {
    if (isDict(node)) {
      for (const [key, value] of Object.entries(node)) {
        const child = [...segs, String(key)];
        const name = formatPath(child);
        if (known.has(name)) walk(value, child);
        else if (!found.includes(name)) found.push(name);
      }
    } else if (Array.isArray(node)) {
      for (const item of node) walk(item, [...segs, ARRAY_ITEM]);
    }
  };
  walk(data, []);
  return found;
}

/**
 * Resolve every mapped field of `template` against `data`.
 *
 * Returns `{fields, tables, warnings}`; unmapped template fields get no entry. The record-level
 * warnings are `unmapped_data` per schema path with a value but no mapped field, and one
 * `unknown_keys` note for record keys the schema does not declare. (Python also reports `invalid`
 * per validation error; the browser has no validator.)
 * @param {object} template  the plain JSON of a template
 * @param {any} data
 * @returns {{fields: Object<string, Resolved>, tables: Object<string, TableResolved>, warnings: FillWarning[]}}
 */
export function resolve(template, data) {
  const schemaPaths = flattenSchema(template.schema);
  const byPath = new Map(schemaPaths.map((sp) => [sp.path, sp]));
  const fields = {};
  const tables = {};
  for (const f of template.fields) {
    if (!f.source || !f.source.paths.length) continue;
    if (f.type === "table") tables[f.id] = resolveTable(f, data, byPath);
    else if (CHOICE_TYPES.includes(f.type)) fields[f.id] = resolveChoice(f, data);
    else fields[f.id] = resolveText(f, data);
  }

  const record = [];
  if (isDict(data)) {
    record.push(...unmapped(template, data, schemaPaths));
    const unknown = unknownKeys(data, new Set(byPath.keys()));
    if (unknown.length) {
      record.push(makeWarning("unknown_keys", `keys not in the schema were ignored: ${unknown.join(", ")}`));
    }
  }
  return { fields, tables, warnings: record };
}
